import{_ as e,o,c as d,af as s}from"./chunks/framework.Dt3O48XQ.js";const _=JSON.parse('{"title":"配置说明","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":null}'),n={name:"guide/configuration.md"};function a(c,t,r,l,p,i){return o(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="配置说明" tabindex="-1">配置说明 <a class="header-anchor" href="#配置说明" aria-label="Permalink to &quot;配置说明&quot;">​</a></h1><p>配置从 <strong>环境变量</strong> 读取，实现见服务端 <strong><code>src/config/index.ts</code></strong>（注释中说明了优先级与生产环境注意点）。加载顺序简述如下：</p><ol><li>按 <strong><code>NODE_ENV</code></strong>（未设置时视为 <code>development</code>）读取 <strong><code>.env.\${NODE_ENV}</code></strong>（例如 <code>.env.development</code>）。</li><li>非 <code>development</code> 时，再尝试加载项目根目录 <strong><code>.env</code></strong>。</li><li>最后再 <strong><code>dotenv.config()</code></strong> 一次，便于系统环境变量或额外 <code>.env</code> 覆盖。</li></ol><p>下文 <strong>「未设置」</strong> 指：对应环境变量在文件中不写、或留空、且进程环境中也未注入。默认值以仓库当前 <code>src/config/index.ts</code> 为准；若你本地改过代码，以运行时代码为准。</p><h2 id="核心配置入口" tabindex="-1">核心配置入口 <a class="header-anchor" href="#核心配置入口" aria-label="Permalink to &quot;核心配置入口&quot;">​</a></h2><ul><li>应用与 Colyseus：<code>src/app.config.ts</code></li><li><strong>环境变量聚合</strong>：<code>src/config/index.ts</code></li><li>小游戏：<code>src/config/minigame.ts</code></li><li>路由前缀：<code>src/routes/index.ts</code></li></ul><h2 id="服务与数据库" tabindex="-1">服务与数据库 <a class="header-anchor" href="#服务与数据库" aria-label="Permalink to &quot;服务与数据库&quot;">​</a></h2><p>示例（<code>.env.development</code> 片段）：</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NODE_ENV=development</span></span>
<span class="line"><span>PORT=2567</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DB_TYPE=mysql</span></span>
<span class="line"><span>DB_HOST=localhost</span></span>
<span class="line"><span>DB_PORT=3306</span></span>
<span class="line"><span>DB_USERNAME=root</span></span>
<span class="line"><span>DB_PASSWORD=your_password</span></span>
<span class="line"><span>DB_DATABASE=your_database</span></span>
<span class="line"><span>DB_SYNCHRONIZE=true</span></span>
<span class="line"><span>DB_LOGGING=true</span></span></code></pre></div><table tabindex="0"><thead><tr><th>变量</th><th>未设置时的含义</th></tr></thead><tbody><tr><td><code>NODE_ENV</code></td><td>视为 <strong><code>development</code></strong>。</td></tr><tr><td><code>PORT</code></td><td><strong><code>2567</code></strong>。</td></tr><tr><td><code>APP_NAME</code></td><td>默认应用名 <strong><code>strataggems-server</code></strong>（展示用，可按项目改名）。</td></tr><tr><td><code>APP_VERSION</code></td><td><strong><code>1.0.0</code></strong>；同时影响 Swagger 等处未单独配置时的版本展示。</td></tr><tr><td><code>DB_TYPE</code></td><td><strong><code>mysql</code></strong>。</td></tr><tr><td><code>DB_HOST</code></td><td><strong><code>localhost</code></strong>。</td></tr><tr><td><code>DB_PORT</code></td><td><strong><code>3306</code></strong>。</td></tr><tr><td><code>DB_USERNAME</code></td><td><strong><code>root</code></strong>。</td></tr><tr><td><code>DB_PASSWORD</code></td><td><strong>空字符串</strong>（若库要求密码，必须显式配置）。</td></tr><tr><td><code>DB_DATABASE</code></td><td><strong><code>strataggems</code></strong>（请改成你的库名）。</td></tr><tr><td><code>DB_SYNCHRONIZE</code></td><td><strong>仅当值为字符串 <code>true</code> 时</strong> 开启 TypeORM 自动同步；<strong>未写或写其它值 → 关闭</strong>。生产务必关闭并改用迁移。</td></tr><tr><td><code>DB_LOGGING</code></td><td><strong>仅当值为 <code>true</code> 时</strong> 打开 SQL 日志；未设置 → <strong>关闭</strong>。</td></tr><tr><td><code>DB_ENTITIES</code> / <code>DB_MIGRATIONS</code> / <code>DB_SUBSCRIBERS</code></td><td>有内置默认 glob；一般不必改，除非目录结构自定义。</td></tr></tbody></table><p>说明：部分文档或旧 README 可能写作 <code>DB_SYNC</code>，<strong>以 <code>DB_SYNCHRONIZE</code> 为准</strong>（与 <code>env.example</code>、<code>.env.development</code> 一致）。</p><h2 id="redis-与-jwt" tabindex="-1">Redis 与 JWT <a class="header-anchor" href="#redis-与-jwt" aria-label="Permalink to &quot;Redis 与 JWT&quot;">​</a></h2><p>示例：</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REDIS_HOST=localhost</span></span>
<span class="line"><span>REDIS_PORT=6379</span></span>
<span class="line"><span>REDIS_PASSWORD=</span></span>
<span class="line"><span>REDIS_DB=0</span></span>
<span class="line"><span>REDIS_KEY_PREFIX=strataggems:</span></span>
<span class="line"><span>REDIS_CONNECT_TIMEOUT=10000</span></span>
<span class="line"><span>REDIS_LAZY_CONNECT=false</span></span>
<span class="line"><span></span></span>
<span class="line"><span>JWT_SECRET=your_jwt_secret_key</span></span>
<span class="line"><span>JWT_EXPIRES_IN=24h</span></span>
<span class="line"><span>JWT_REFRESH_SECRET=your_refresh_secret_key</span></span>
<span class="line"><span>JWT_REFRESH_EXPIRES_IN=7d</span></span></code></pre></div><table tabindex="0"><thead><tr><th>变量</th><th>未设置时的含义</th></tr></thead><tbody><tr><td><code>REDIS_HOST</code></td><td><strong><code>localhost</code></strong>。</td></tr><tr><td><code>REDIS_PORT</code></td><td><strong><code>6379</code></strong>。</td></tr><tr><td><code>REDIS_PASSWORD</code></td><td><strong>不设置</strong> → 客户端以<strong>无密码</strong>连接；若 Redis 启用了 requirepass，必须配置。</td></tr><tr><td><code>REDIS_DB</code></td><td><strong><code>0</code></strong>。</td></tr><tr><td><code>REDIS_KEY_PREFIX</code></td><td><strong><code>strataggems:</code></strong>（键前缀，多项目共 Redis 时可区分命名空间）。</td></tr><tr><td><code>REDIS_CONNECT_TIMEOUT</code></td><td><strong><code>10000</code></strong>（毫秒）。</td></tr><tr><td><code>REDIS_LAZY_CONNECT</code></td><td><strong>仅当值为 <code>true</code> 时</strong> 懒连接；未设置 → <strong>false</strong>（启动期即尝试连接，行为以 ioredis 为准）。</td></tr><tr><td><code>JWT_SECRET</code></td><td>使用代码内 <strong>开发用占位字符串</strong>（<strong>生产必须改</strong>，否则严重不安全）。</td></tr><tr><td><code>JWT_EXPIRES_IN</code></td><td><strong><code>24h</code></strong>（字符串形式，供 <code>jsonwebtoken</code> 等使用；其它模块若按秒解析，请以该模块实现为准）。</td></tr><tr><td><code>JWT_REFRESH_SECRET</code></td><td>使用代码内 <strong>开发用占位</strong>（<strong>生产必须改</strong>）。</td></tr><tr><td><code>JWT_REFRESH_EXPIRES_IN</code></td><td><strong><code>7d</code></strong>。</td></tr></tbody></table><p><strong>匹配、进房鉴权、世界聊天跨实例</strong>等依赖 Redis；未启动 Redis 或地址错误时，相关功能会失败或降级（参见各专题文档）。</p><h2 id="房间、聊天与压测" tabindex="-1">房间、聊天与压测 <a class="header-anchor" href="#房间、聊天与压测" aria-label="Permalink to &quot;房间、聊天与压测&quot;">​</a></h2><p>示例：</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>COLYSEUS_MAX_CLIENTS=100</span></span>
<span class="line"><span>CHAT_ROOM_MAX_CLIENTS=5000</span></span>
<span class="line"><span>CHAT_WORLD_REDIS_CHANNEL=colyseus:chat:world</span></span>
<span class="line"><span>LOADTEST_ROOM_MAX_CLIENTS=10000</span></span>
<span class="line"><span>LOADTEST_ROOM_ENABLED=true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>COLYSEUS_PING_INTERVAL=3000</span></span>
<span class="line"><span>COLYSEUS_PING_MAX_RETRIES=3</span></span></code></pre></div><table tabindex="0"><thead><tr><th>变量</th><th>未设置时的含义</th></tr></thead><tbody><tr><td><code>COLYSEUS_MAX_CLIENTS</code></td><td>全局预留上限 <strong><code>100</code></strong>（单房上限等以房间类型为准，见 <code>app.config</code>）。</td></tr><tr><td><code>CHAT_ROOM_MAX_CLIENTS</code></td><td>聊天房 <strong><code>Room.maxClients</code> 默认目标 <code>5000</code></strong>，实际会限制在 <strong>1～65535</strong> 之间。</td></tr><tr><td><code>CHAT_WORLD_REDIS_CHANNEL</code></td><td>世界频道 Pub/Sub 使用 <strong><code>colyseus:chat:world</code></strong>；多实例必须一致。</td></tr><tr><td><code>LOADTEST_ROOM_MAX_CLIENTS</code></td><td>压测房单房上限默认 <strong><code>10000</code></strong>（同样裁剪到合法范围）。</td></tr><tr><td><code>LOADTEST_ROOM_ENABLED</code></td><td><strong>仅当值为字符串 <code>false</code> 时</strong> 关闭压测房；<strong>未设置或其它值 → 视为开启</strong>（与「默认允许压测房」一致）。生产请显式设为 <strong><code>false</code></strong>。</td></tr><tr><td><code>COLYSEUS_PING_INTERVAL</code></td><td><strong><code>3000</code></strong>（毫秒）。</td></tr><tr><td><code>COLYSEUS_PING_MAX_RETRIES</code></td><td><strong><code>3</code></strong>。</td></tr></tbody></table><p>对局重连窗口（<code>game_room</code>）由 <strong><code>MATCH_RECONNECT_WINDOW_MS</code></strong> 控制，<strong>未设置</strong> 时一般为 <strong><code>15000</code></strong> 毫秒（见 <a href="/xcs.github.io/rooms/frame-sync-game-room.html">帧同步与游戏房</a>）。</p><h2 id="swagger-可选" tabindex="-1">Swagger（可选） <a class="header-anchor" href="#swagger-可选" aria-label="Permalink to &quot;Swagger（可选）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>未设置时的含义</th></tr></thead><tbody><tr><td><code>SWAGGER_ENABLED</code></td><td><strong>仅当值为 <code>false</code> 时</strong> 关闭；未设置 → <strong>开启</strong>。</td></tr><tr><td><code>SWAGGER_PATH</code></td><td><strong><code>/api-docs</code></strong>。</td></tr><tr><td><code>SWAGGER_TITLE</code> / <code>SWAGGER_DESCRIPTION</code> / <code>SWAGGER_VERSION</code></td><td>有中文默认文案；<code>SWAGGER_VERSION</code> 还可回退到 <code>APP_VERSION</code>。</td></tr><tr><td><code>SWAGGER_SERVER_URL</code></td><td>默认 <strong><code>http://localhost:\${PORT}</code></strong>。</td></tr><tr><td><code>SWAGGER_CONTACT_*</code></td><td>未设置则联系信息为空块，不影响启动。</td></tr></tbody></table><h2 id="实践建议" tabindex="-1">实践建议 <a class="header-anchor" href="#实践建议" aria-label="Permalink to &quot;实践建议&quot;">​</a></h2><ul><li>生产环境将 <strong><code>DB_SYNCHRONIZE</code></strong> 设为 <strong><code>false</code></strong>，用迁移管理表结构。</li><li><strong><code>JWT_SECRET</code></strong>、<strong><code>JWT_REFRESH_SECRET</code></strong>、数据库与 Redis 密码使用高强度随机值。</li><li>多实例部署：<strong>Redis 必达</strong>，且 <strong><code>CHAT_WORLD_REDIS_CHANNEL</code></strong> 各节点一致。</li><li>生产将 <strong><code>LOADTEST_ROOM_ENABLED=false</code></strong>，避免误暴露无鉴权压测房。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/xcs.github.io/guide/installation.html">安装指南</a></li><li><a href="/xcs.github.io/guide/project-structure.html">项目结构</a>（<code>src/config</code> 与 <code>app.config</code> 关系）</li></ul>`,27)])])}const E=e(n,[["render",a]]);export{_ as __pageData,E as default};
